function Main() {
    const tick = useObservable(0);
    const closeTick = useObservable(0);
    const scheme = useColorScheme();
    const dismiss = Navigation.useDismiss();
    useEffect(() => {
        _themeDark = scheme === "dark";
        lg("主题", "系统深浅色 = " + (scheme === "dark" ? "深色" : "浅色"));
        try {
            if (_wv && _wv.evaluateJavaScript) {
                _wv.evaluateJavaScript("(function(){var d=document.documentElement;if(d){if(" + _themeDark + "){d.setAttribute('data-theme','dark');}else{d.removeAttribute('data-theme');}}})()")
                    .catch(function () { });
            }
        }
        catch (e) { }
    }, [scheme]);
    useEffect(() => {
        _setTick = () => { tick.setValue(tick.value + 1); };
        _closeTick = () => { closeTick.setValue(closeTick.value + 1); };
        if (!_wv)
            _wv = new WebViewController();
        initBoard();
    }, []);
    useEffect(() => {
        if (_closeRequested) {
            lg("收起", "界面已收起");
            _closeRequested = false;
            try {
                dismiss();
            }
            catch (e) {
                console.error("[看板] " + stamp() + " 出错 · 收起界面失败:", e);
            }
        }
    }, [closeTick.value]);
    return (<ZStack alignment="top" frame={{ maxWidth: "infinity", maxHeight: "infinity" }} background={scheme === "dark" ? "#121217" : "#f2f5f9"} ignoresSafeArea={true}>
      {_wv ?
            <WebView controller={_wv} ignoresSafeArea={true} frame={{ maxWidth: "infinity", maxHeight: "infinity" }}/> :
            null}
      {_loading ?
            <ProgressView style={"large"} frame={{ maxWidth: "infinity", maxHeight: "infinity" }}/> :
            null}
    </ZStack>);
}
_mainEl = <Main />;
async function run() {
    await Navigation.present({ element: _mainEl, modalPresentationStyle: "overFullScreen" });
    if (_exitRequested) {
        lg("退出", "关闭实例");
        try {
            Script.exit();
        }
        catch (e) {
            console.error("[看板] " + stamp() + " 出错 · 脚本退出失败:", e);
        }
    }
    else {
        lg("收起", "界面已收起（实例存活）");
    }
}
void run();
